from rest_framework.views import APIView
from rest_framework.permissions import IsAuthenticated
from rest_framework.exceptions import PermissionDenied
from rest_framework.response import Response
from rest_framework_csv.renderers import CSVRenderer
from .models import EmployeePayrollRecord

RESTRICTED_PAYROLL_FIELDS = {'net_salary', 'base_salary', 'bank_account_number', 'ssn', 'routing_number'}
BASE_ALLOWED_FIELDS = {'id', 'full_name', 'department', 'title', 'hire_date'}

class PayrollCSVExportView(APIView):
    permission_classes = [IsAuthenticated]
    renderer_classes = [CSVRenderer]

    def get(self, request):
        user = request.user
        queryset = EmployeePayrollRecord.objects.filter(company=user.company)
        columns_param = request.query_params.get('columns')

        if columns_param:
            requested_columns = set(col.strip() for col in columns_param.split(','))
        else:
            requested_columns = BASE_ALLOWED_FIELDS

        # Check field permissions: only HR admins may request restricted salary and banking fields
        if requested_columns.intersection(RESTRICTED_PAYROLL_FIELDS) and not user.has_perm('payroll.view_sensitive_payroll'):
            raise PermissionDenied("You do not have permission to export sensitive payroll columns")

        allowed_columns = list(requested_columns.intersection(BASE_ALLOWED_FIELDS | RESTRICTED_PAYROLL_FIELDS))
        data = list(queryset.values(*allowed_columns))
        return Response(data)
